80	    /**
81	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
82	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
86	
87	    /**
88	     * Domains that supply disposable / throwaway mailboxes. An owner whose email domain matches one of
89	     * these (compared case-insensitively) is rejected. Values are stored lower-cased for comparison.
90	     */
91	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
92	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
