189	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
190	        currentOwner.setLastName(ownerFieldsDto.getLastName());
191	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
192	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
193	        this.clinicService.saveOwner(currentOwner);
194	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
