274	    /**
275	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
276	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
277	     *
278	     * @param fields the submitted owner fields
279	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
280	     *                                        {@code null} or blank, or if address is blank after
281	     *                                        normalization
282	     */
283	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
284	        List<String> missing = new ArrayList<>();
285	        if (isBlank(fields.getFirstName())) {
286	            missing.add("firstName");
287	        }
288	        if (isBlank(fields.getLastName())) {
289	            missing.add("lastName");
290	        }
291	        if (isBlank(normalizeAddress(fields.getAddress()))) {
292	            missing.add("address");
293	        }
294	        if (isBlank(fields.getCity())) {
295	            missing.add("city");
296	        }
297	        if (isBlank(fields.getTelephone())) {
298	            missing.add("telephone");
299	        }
300	        if (!missing.isEmpty()) {
301	            throw new RequiredFieldsMissingException(missing);
302	        }
303	    }
304	
305	    private boolean isBlank(String value) {
306	        return value == null || value.isBlank();
307	    }
308	
309	    /**
310	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
311	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
312	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
313	     */
314	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
315	        "NSW", new int[] {2000, 2099},
316	        "VIC", new int[] {3000, 3099},
317	        "QLD", new int[] {4000, 4099});
318	
319	    /**
320	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
321	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
322	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
323	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
324	     *
325	     * @param postcode the submitted postcode, or {@code null} when omitted
326	     * @param city the owner's city, used to derive the region whose range constrains the postcode
327	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
328	     *                                  city's region
329	     */
330	    private void validatePostcode(String postcode, String city) {
331	        if (postcode == null) {
332	            return;
333	        }
334	        if (!postcode.matches("[0-9]{4}")) {
335	            throw new InvalidPostcodeException(postcode);
336	        }
337	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
338	        if (range == null) {
339	            return;
340	        }
341	        int value = Integer.parseInt(postcode);
342	        if (value < range[0] || value > range[1]) {
343	            throw new InvalidPostcodeException(postcode);
344	        }
345	    }
346	
347	    /**
348	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
349	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
350	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
351	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
352	     * <p>
353	     * Where a per-country rule is defined the national-number length is validated against the country
354	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
355	     * requires exactly 10.
356	     *
357	     * @param telephone the raw telephone value from the request
358	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
359	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
360	     */
361	    private String normalizeTelephone(String telephone) {
362	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
363	        String digits;
364	        if (cleaned.startsWith("+")) {
365	            digits = cleaned.substring(1);
366	        } else {
367	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
368	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
369	            digits = "61" + national;
370	        }
371	        if (!digits.matches("[0-9]{8,15}")) {
372	            throw new InvalidTelephoneException(cleaned);
373	        }
374	        // Validate the national-number length against the country code where a rule is defined.
375	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
376	            throw new InvalidTelephoneException(cleaned);
377	        }
378	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
379	            throw new InvalidTelephoneException(cleaned);
380	        }
381	        return "+" + digits;
382	    }
383	
384	    /**
385	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
386	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
387	     * lower-cased.
388	     *
389	     * @param email the raw email value from the request, or {@code null} if omitted
390	     * @return the lower-cased email, or {@code null} if none was supplied
391	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
392	     */
393	    private String normalizeEmail(String email) {
394	        if (email == null) {
395	            return null;
396	        }
397	        String trimmed = email.strip();
398	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
399	            throw new InvalidEmailException(email);
400	        }
401	        String normalized = trimmed.toLowerCase(Locale.ROOT);
402	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
403	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
404	            throw new DisposableEmailDomainException(domain);
405	        }
406	        return normalized;
407	    }
408	
409	    /**
410	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
411	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
412	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
413	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
414	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
415	     *
416	     * @param address the raw address value from the request (may be {@code null})
417	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
418	     */
419	    private String normalizeAddress(String address) {
420	        if (address == null) {
421	            return "";
422	        }
423	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
424	        if (collapsed.isEmpty()) {
425	            return "";
426	        }
427	        String[] tokens = collapsed.split(" ");
428	        StringBuilder sb = new StringBuilder(collapsed.length());
429	        for (int i = 0; i < tokens.length; i++) {
430	            if (i > 0) {
431	                sb.append(' ');
432	            }
433	            sb.append(expandAddressAbbreviation(tokens[i]));
434	        }
435	        return sb.toString();
436	    }
437	
438	    /**
439	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
440	     * returns the token unchanged when it is not a recognised abbreviation.
441	     *
442	     * @param token an upper-cased whole-word address token
443	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
444	     */
445	    private String expandAddressAbbreviation(String token) {
446	        return switch (token) {
447	            case "ST" -> "STREET";
448	            case "RD" -> "ROAD";
449	            case "AVE" -> "AVENUE";
450	            default -> token;
451	        };
452	    }
453	
454	    /**
455	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
456	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
457	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
458	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
459	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
460	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
461	     * sequence number is assigned.
462	     *
463	     * @param owner the owner being created, with normalized telephone and postcode already set
464	     * @return the assigned customer code
465	     */
466	    private String generateCustomerCode(Owner owner) {
467	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
468	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
469	            .substring(0, 8).toUpperCase(Locale.ROOT);
470	        return region + "-" + hash8;
471	    }
472	
473	    /**
474	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
475	     *
476	     * @param value the value to hash
477	     * @return the 64-character lower-case hex SHA-256 digest
478	     */
479	    private String sha256Hex(String value) {
480	        try {
481	            byte[] digest = MessageDigest.getInstance("SHA-256")
482	                .digest(value.getBytes(StandardCharsets.UTF_8));
483	            StringBuilder sb = new StringBuilder(digest.length * 2);
484	            for (byte b : digest) {
485	                sb.append(String.format("%02x", b));
486	            }
487	            return sb.toString();
488	        } catch (NoSuchAlgorithmException e) {
489	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
490	        }
491	    }
492	
493	    /**
494	     * Counts how many existing owners already share the given first name and last name, compared
495	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
496	     * owner being created.
497	     *
498	     * @param firstName the first name of the owner being created
499	     * @param lastName the last name of the owner being created
500	     * @return the number of existing owners with the same first and last name (case-insensitively)
501	     */
502	    private int countNamesakes(String firstName, String lastName) {
503	        return (int) this.clinicService.findAllOwners().stream()
504	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
505	                && lastName.equalsIgnoreCase(existing.getLastName()))
506	            .count();
507	    }
508	
509	    /**
510	     * Computes the size of the owner's household: the number of existing owners already sharing the given
511	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
512	     * owner is persisted, so adding one for the owner yields the household's total membership including it
513	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
514	     * the deterministic {@code householdId} (derived from last name and postcode).
515	     *
516	     * @param householdId the computed household identifier of the owner being created
517	     * @return the household size including the owner being created (at least 1)
518	     */
519	    private int countHouseholdSize(String householdId) {
520	        long existing = this.clinicService.findAllOwners().stream()
521	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
522	            .count();
523	        return (int) existing + 1;
524	    }
525	
526	    /**
527	     * The maximum number of owners permitted in a single city. A create request whose city already
528	     * holds this many owners is rejected.
529	     */
530	    private static final int CITY_OWNER_LIMIT = 50;
531	
532	    /**
533	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
534	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
535	     * differing only in the casing of their city share one capacity pool. The count is taken before the
536	     * new owner is persisted, so it excludes the owner being created.
537	     *
538	     * @param city the city of the owner being created
539	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
540	     */
541	    private void rejectCityAtCapacity(String city) {
542	        long existing = this.clinicService.findAllOwners().stream()
543	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
544	            .count();
545	        if (existing >= CITY_OWNER_LIMIT) {
546	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
547	        }
548	    }
549	
550	    /**
551	     * The maximum number of owners permitted to be created in a single day. A create request whose
552	     * registration date already holds this many owners is rejected.
553	     */
554	    private static final int DAILY_OWNER_LIMIT = 100;
555	
556	    /**
557	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
558	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
559	     * persisted, so it excludes the owner being created.
560	     *
561	     * @param registrationDate the registration date of the owner being created
562	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
563	     */
564	    /**
565	     * Adjusts an effective registration date so that it always falls on a business day. When the given
566	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
567	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
568	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
569	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
570	     * business-day-adjusted date.
571	     *
572	     * @param date the effective registration date, supplied or defaulted
573	     * @return the same date when it is a weekday, otherwise the next Monday
574	     */
575	    private LocalDate rollToBusinessDay(LocalDate date) {
576	        DayOfWeek day = date.getDayOfWeek();
577	        if (day == DayOfWeek.SATURDAY) {
578	            return date.plusDays(2);
579	        }
580	        if (day == DayOfWeek.SUNDAY) {
581	            return date.plusDays(1);
582	        }
583	        return date;
584	    }
585	
586	    /**
587	     * The number of owners that must already exist for a given day before a further create is flagged as a
588	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
589	     * the created owner carries {@code bulkSignupWarning = true}.
590	     */
591	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
592	
593	    /**
594	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
595	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
596	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
597	     * the daily create-limit rule's accumulation path.
598	     *
599	     * @param registrationDate the registration date of the owner being created
600	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
601	     */
602	    private boolean isBulkSignupDay(LocalDate registrationDate) {
603	        long existing = this.clinicService.findAllOwners().stream()
604	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
605	            .count();
606	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
607	    }
608	
609	    /**
610	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
611	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
612	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
613	     * made against the supplied value before any business-day adjustment.
614	     *
615	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
616	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
617	     */
618	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
619	        if (registrationDate == null) {
620	            return;
621	        }
622	        LocalDate today = LocalDate.now();
623	        if (registrationDate.isAfter(today)) {
624	            throw new FutureRegistrationDateException(registrationDate, today);
625	        }
626	    }
627	
628	    private void rejectDailyLimitReached(LocalDate registrationDate) {
629	        long existing = this.clinicService.findAllOwners().stream()
630	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
631	            .count();
632	        if (existing >= DAILY_OWNER_LIMIT) {
633	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
634	        }
635	    }
636	
637	    /**
638	     * Rejects a create request whose owner collides with an existing owner on the single derived
639	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
640	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
641	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
642	     * household (same {@code householdId}) with different telephones have different keys and are both
643	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
644	     * been computed (deterministically from the last name and postcode) before this check runs, so the
645	     * key compared here is the same one that is later returned.
646	     *
647	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
648	     * @throws DuplicateIdentityException if an existing owner has the same identity key
649	     */
650	    private void rejectDuplicateIdentity(Owner owner) {
651	        String key = identityKey(owner);
652	        boolean taken = this.clinicService.findAllOwners().stream()
653	            .anyMatch(existing -> key.equals(identityKey(existing)));
654	        if (taken) {
655	            throw new DuplicateIdentityException(key);
656	        }
657	    }
658	
659	    /**
660	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
661	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
662	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
663	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
664	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
665	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
666	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
667	     * <p>
668	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
669	     * postcode is now exactly the household key, so such an owner is a known household member rather than
670	     * a suspected duplicate.
671	     *
672	     * @param owner the owner being created, with normalized telephone and validated postcode already set
673	     * @param sharesHousehold whether the create declared the owner a household member
674	     */
675	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
676	        Integer matchId = null;
677	        if (!sharesHousehold && owner.getPostcode() != null) {
678	            matchId = this.clinicService.findAllOwners().stream()
679	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
680	                    && owner.getPostcode().equals(existing.getPostcode())
681	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
682	                .map(Owner::getId)
683	                .filter(id -> id != null)
684	                .min(Comparator.naturalOrder())
685	                .orElse(null);
686	        }
687	        owner.setPossibleDuplicate(matchId != null);
688	        owner.setPossibleDuplicateOf(matchId);
689	    }
690	
691	    private boolean telephonesEqual(String a, String b) {
692	        return a == null ? b == null : a.equals(b);
693	    }
694	
695	    /**
696	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
697	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
698	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
699	     * Telephone and email are stored already normalized, so the stored values are used directly.
700	     *
701	     * @param owner the owner whose identity key is being derived
702	     * @return the owner's identity key
703	     */
704	    private String identityKey(Owner owner) {
705	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
706	        String email = owner.getEmail() == null ? "" : owner.getEmail();
707	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
708	        return telephone + "|" + email + "|" + householdId;
709	    }
710	
711	    /**
712	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
713	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
714	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
715	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
716	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
717	     * whether or not {@code sharesHousehold} was requested.
718	     *
719	     * @param owner the owner being created, with its validated postcode already set
720	     * @return the deterministic household identifier
721	     */
722	    private String computeHouseholdId(Owner owner) {
723	        String normalizedLastName = normalizeForComparison(owner.getLastName());
724	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
725	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
726	    }
727	
728	    /**
729	     * Rejects a create request whose owner would join an existing household without declaring it. The
730	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
731	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
732	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
733	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
734	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
735	     *
736	     * @param owner the owner being created, with its computed {@code householdId} already assigned
737	     * @throws HouseholdDuplicateException if an existing owner already shares the household
738	     */
739	    private void rejectHouseholdDuplicate(Owner owner) {
740	        String householdId = owner.getHouseholdId();
741	        boolean shared = this.clinicService.findAllOwners().stream()
742	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
743	        if (shared) {
744	            throw new HouseholdDuplicateException(householdId);
745	        }
746	    }
747	
748	    /**
749	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
750	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
751	     * lower-cased.
752	     *
753	     * @param value the raw value to normalize (may be {@code null})
754	     * @return the normalized value, or an empty string when {@code value} is {@code null}
755	     */
756	    private String normalizeForComparison(String value) {
757	        if (value == null) {
758	            return "";
759	        }
760	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
761	    }
762	}
